package com.proxy.upload

import java.io.{ByteArrayInputStream, ByteArrayOutputStream, InputStream}
import java.net.{HttpURLConnection, URL}
import java.nio.charset.{Charset, StandardCharsets}
import java.util.Base64
import java.util.regex.Pattern
import javax.net.ssl.HttpsURLConnection

object EncodingNormalizer {
  private val ALLOWED_CHARSETS = Set("UTF-8", "ISO-8859-1", "US-ASCII", "UTF-16BE", "UTF-16LE")

  def normalizeCharset(declared: String): Option[Charset] = {
    val upper = declared.trim.toUpperCase.replaceAll("[^A-Z0-9\\-]", "")
    if (ALLOWED_CHARSETS.contains(upper)) Some(Charset.forName(upper))
    else None
  }

  def detectBOM(data: Array[Byte]): Option[Charset] = {
    if (data.length >= 3 && data(0) == 0xEF.toByte && data(1) == 0xBB.toByte && data(2) == 0xBF.toByte)
      Some(StandardCharsets.UTF_8)
    else if (data.length >= 2 && data(0) == 0xFE.toByte && data(1) == 0xFF.toByte)
      Some(StandardCharsets.UTF_16BE)
    else if (data.length >= 2 && data(0) == 0xFF.toByte && data(1) == 0xFE.toByte)
      Some(StandardCharsets.UTF_16LE)
    else None
  }
}

class ContentTypeParser(raw: String) {
  private val parts = raw.split(";")
  val mimeType: String = parts.headOption.map(_.trim.toLowerCase).getOrElse("application/octet-stream")
  val charset: Option[String] = parts.tail.map(_.trim).find(_.startsWith("charset=")).map(_.substring(8).trim)
  val boundary: Option[String] = parts.tail.map(_.trim).find(_.startsWith("boundary=")).map(_.substring(9).trim)
}

trait UploadValidator {
  def validate(content: Array[Byte], contentType: ContentTypeParser): Either[String, Array[Byte]]
}

class TextValidator extends UploadValidator {
  private val MAX_SIZE = 1024 * 1024 // 1MB
  private val FORBIDDEN_PATTERNS = List(
    "<script", "javascript:", "on[a-z]+\\s*=", "<iframe", "<object", "<embed"
  )
  // Precompile patterns and use find() to avoid catastrophic backtracking (ReDoS)
  private val FORBIDDEN_REGEXES = FORBIDDEN_PATTERNS.map { p =>
    Pattern.compile(p, Pattern.CASE_INSENSITIVE | Pattern.DOTALL)
  }

  override def validate(content: Array[Byte], contentType: ContentTypeParser): Either[String, Array[Byte]] = {
    if (content.length > MAX_SIZE) return Left("Content too large")

    val declaredCharset = contentType.charset.flatMap(EncodingNormalizer.normalizeCharset)
    val bomCharset = EncodingNormalizer.detectBOM(content)

    // Use BOM charset if present, otherwise fall back to declared
    val effectiveCharset = bomCharset.orElse(declaredCharset).getOrElse(StandardCharsets.UTF_8)

    val text = new String(content, effectiveCharset)

    // Normalize to UTF-8 for security scanning
    val normalized = text.getBytes(StandardCharsets.UTF_8)
    val normalizedText = new String(normalized, StandardCharsets.UTF_8)

    FORBIDDEN_REGEXES.foreach { regex =>
      if (regex.matcher(normalizedText).find()) {
        return Left(s"Forbidden content pattern detected")
      }
    }

    // Return normalized UTF-8 content to prevent encoding confusion downstream
    Right(normalized)
  }
}

class ProxyUploadHandler(backendUrl: String) {
  private val textValidator = new TextValidator()

  private def resolveValidator(mimeType: String): Option[UploadValidator] = mimeType match {
    case t if t.startsWith("text/") => Some(textValidator)
    case "application/json" => Some(textValidator)
    case "application/xml" => Some(textValidator)
    case _ => None
  }

  def processUpload(content: Array[Byte], contentTypeHeader: String): Either[String, ProxyResult] = {
    val contentType = new ContentTypeParser(contentTypeHeader)

    val validator = resolveValidator(contentType.mimeType)

    val validatedContent = validator match {
      case Some(v) => v.validate(content, contentType) match {
        case Left(err) => return Left(err)
        case Right(data) => data
      }
      case None => content
    }

    forwardToBackend(validatedContent, contentTypeHeader)
  }

  private def transcodeForBackend(content: Array[Byte], contentType: ContentTypeParser): Array[Byte] = {
    val declaredCharset = contentType.charset.flatMap(EncodingNormalizer.normalizeCharset)
    val bomCharset = EncodingNormalizer.detectBOM(content)

    // Priority: BOM takes precedence over declared for transcoding (consistent with validation)
    val sourceCharset = bomCharset.orElse(declaredCharset).getOrElse(StandardCharsets.UTF_8)
    val text = new String(content, sourceCharset)
    text.getBytes(StandardCharsets.UTF_8)
  }

  private def forwardToBackend(content: Array[Byte], contentTypeHeader: String): Either[String, ProxyResult] = {
    try {
      val contentType = new ContentTypeParser(contentTypeHeader)
      val transcoded = if (contentType.mimeType.startsWith("text/")) {
        transcodeForBackend(content, contentType)
      } else {
        content
      }

      // Simulate forwarding
      Right(ProxyResult(200, transcoded, s"${contentType.mimeType}; charset=UTF-8"))
    } catch {
      case e: Exception => Left(s"Backend error: ${e.getMessage}")
    }
  }
}

case class ProxyResult(status: Int, body: Array[Byte], contentType: String)

object ProxyApp {
  def main(args: Array[String]): Unit = {
    val handler = new ProxyUploadHandler("https://internal-backend.example.com/upload")
    // Entry point for proxy service
    println("Upload proxy initialized")
  }
}
